  "use strict";

  var ROWS = 20;
  var COLS = 10;
  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
  var PREVIEW = 1;
  var LINES_PER_LEVEL = 10;
  var LOCK_DELAY_TICKS = 2;   // gravity steps a piece may spend unable to fall
  var MAX_LOCK_RESETS = 3;    // times per piece a sideways move or soft drop restarts the delay

  // Points for rows cleared at once, times the level. Clearing rows together
  // must always beat clearing the same rows one at a time.
  var CLEAR_POINTS = [0, 100, 300, 500, 800];
  var SOFT_DROP_POINTS = 1;   // per cell moved down by soft drop
  var HARD_DROP_POINTS = 2;   // per cell dropped by hard drop

  // Each shape is a square matrix; spawn puts its filled cells in rows 0-1.
  var SHAPES = {
    I: { m: ["....", "IIII", "....", "...."], row: -1, col: 3 },
    O: { m: ["OO", "OO"], row: 0, col: 4 },
    T: { m: [".T.", "TTT", "..."], row: 0, col: 3 },
    S: { m: [".SS", "SS.", "..."], row: 0, col: 3 },
    Z: { m: ["ZZ.", ".ZZ", "..."], row: 0, col: 3 },
    J: { m: ["J..", "JJJ", "..."], row: 0, col: 3 },
    L: { m: ["..L", "LLL", "..."], row: 0, col: 3 }
  };

  // ---- State ----
  var board;        // board[row][col] = "" or piece letter
  var current;      // { type, matrix, row, col, lockTicks, lockResets } or null
  var held;         // letter in the hold slot, or null
  var holdUsed;     // true after a hold, until the next piece locks
  var next;         // upcoming piece letters, soonest first
  var scripted;     // true while `next` comes from a test-supplied queue
  var bag = [];
  var score, level, lines, status;
  var timer = null;
  var timerInterval = 0;

  function emptyBoard() {
    var b = [];
    for (var r = 0; r < ROWS; r++) {
      var row = [];
      for (var c = 0; c < COLS; c++) row.push("");
      b.push(row);
    }
    return b;
  }

  function randomType() {
    if (bag.length === 0) {
      bag = TYPES.slice();
      for (var i = bag.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
      }
    }
    return bag.pop();
  }

  function fillPreview() {
    if (scripted) return;
    while (next.length < PREVIEW) next.push(randomType());
  }

  function shapeCells(matrix, row, col) {
    var cells = [];
    for (var r = 0; r < matrix.length; r++) {
      for (var c = 0; c < matrix[r].length; c++) {
        if (matrix[r][c] !== ".") cells.push([row + r, col + c]);
      }
    }
    return cells;
  }

  function fits(matrix, row, col) {
    var cells = shapeCells(matrix, row, col);
    for (var i = 0; i < cells.length; i++) {
      var r = cells[i][0], c = cells[i][1];
      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
      if (board[r][c] !== "") return false;
    }
    return true;
  }

  // Milliseconds between gravity steps at the current level.
  function dropInterval() {
    return Math.max(100, 1000 - (level - 1) * 100);
  }

  function spawn() {
    if (next.length === 0) scripted = false;
    fillPreview();
    var type = next.shift();
    fillPreview();
    enter(type);
  }

  // Puts a piece of the given type at the spawn position, or ends the game.
  function enter(type) {
    var s = SHAPES[type];
    var piece = {
      type: type, matrix: s.m.slice(), row: s.row, col: s.col,
      lockTicks: 0,   // consecutive gravity steps spent unable to fall
      lockResets: 0   // lifetime count of lock-delay restarts
    };
    if (!fits(piece.matrix, piece.row, piece.col)) {
      current = null;
      status = "gameover";
      stopTimer();
      return;
    }
    current = piece;
  }

  function lock() {
    var cells = shapeCells(current.matrix, current.row, current.col);
    for (var i = 0; i < cells.length; i++) {
      board[cells[i][0]][cells[i][1]] = current.type;
    }
    current = null;
    holdUsed = false;
    clearLines();
    spawn();
  }

  // Sets the falling piece aside. The first hold brings in the next piece;
  // later holds swap with the held one. Once per piece until it locks.
  function hold() {
    if (!current || holdUsed) return;
    var type = current.type;
    current = null;
    holdUsed = true;
    if (held === null) {
      held = type;
      spawn();
    } else {
      var out = held;
      held = type;
      enter(out);
    }
  }

  // Removes every full row; rows above drop down.
  function clearLines() {
    var kept = board.filter(function (row) {
      return row.some(function (v) { return v === ""; });
    });
    var cleared = ROWS - kept.length;
    if (cleared === 0) return;
    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
    board = kept;
    // Points use the level the clear was made at.
    score += CLEAR_POINTS[Math.min(cleared, 4)] * level;
    var levelsGained = Math.floor((lines + cleared) / LINES_PER_LEVEL) -
      Math.floor(lines / LINES_PER_LEVEL);
    lines += cleared;
    if (levelsGained > 0) setLevelValue(level + levelsGained);
  }

  // Changes the level and keeps the gravity timer in step with it.
  function setLevelValue(n) {
    level = n;
    if (timer !== null && timerInterval !== dropInterval()) startTimer();
  }

  function tryMove(dr, dc) {
    if (!current) return false;
    if (!fits(current.matrix, current.row + dr, current.col + dc)) return false;
    current.row += dr;
    current.col += dc;
    return true;
  }

  // The single gravity step, used by the real timer and tick().
  // A step that cannot move the piece down counts one tick of lock delay.
  // Returns true if the piece moved down.
  function gravityStep() {
    if (status !== "running" || !current) return false;
    if (tryMove(1, 0)) {
      current.lockTicks = 0;
      return true;
    }
    current.lockTicks++;
    if (current.lockTicks >= LOCK_DELAY_TICKS) lock();
    return false;
  }

  // Restarts a running lock delay, up to MAX_LOCK_RESETS times per piece.
  function restartLockDelay() {
    if (current.lockTicks > 0 && current.lockResets < MAX_LOCK_RESETS) {
      current.lockResets++;
      current.lockTicks = 0;
    }
  }

  // Soft drop. If the piece cannot fall, it counts like a sideways move:
  // it restarts a running lock delay and never adds a lock tick itself.
  function softDrop() {
    if (tryMove(1, 0)) {
      current.lockTicks = 0;
      score += SOFT_DROP_POINTS;
    } else {
      restartLockDelay();
    }
  }

  // Left/right. A move made while the lock delay is running restarts it.
  function shift(dc) {
    if (tryMove(0, dc)) restartLockDelay();
  }

  // Clockwise rotation. Tries the rotated shape in place, then shifted
  // sideways; if none fit, the piece is left unchanged.
  function rotateCW() {
    if (!current) return;
    var m = current.matrix;
    var n = m.length;
    var rotated = [];
    for (var r = 0; r < n; r++) {
      var line = "";
      for (var c = 0; c < n; c++) line += m[n - 1 - c][r];
      rotated.push(line);
    }
    var kicks = [0, -1, 1, -2, 2];
    for (var i = 0; i < kicks.length; i++) {
      var nc = current.col + kicks[i];
      if (fits(rotated, current.row, nc)) {
        current.matrix = rotated;
        current.col = nc;
        return;
      }
    }
  }

  // Hard drop skips the lock delay.
  function hardDrop() {
    if (!current) return;
    while (tryMove(1, 0)) score += HARD_DROP_POINTS;
    lock();
  }

  function applyInput(action) {
    if (status !== "running" || !current) return;
    switch (action) {
      case "left": shift(-1); break;
      case "right": shift(1); break;
      case "softDrop": softDrop(); break;
      case "hardDrop": hardDrop(); break;
      case "rotateCW":
      case "rotate": rotateCW(); break;
      case "hold": hold(); break;
    }
  }

  // ---- Timer ----
  function stopTimer() {
    if (timer !== null) { clearInterval(timer); timer = null; }
  }

  function startTimer() {
    stopTimer();
    timerInterval = dropInterval();
    timer = setInterval(function () {
      gravityStep();
      render();
    }, timerInterval);
  }

  // ---- Rendering (synchronous) ----
  var boardEl = document.getElementById("board");
  var nextEl = document.getElementById("next");
  var holdEl = document.getElementById("hold");
  var boardWrapEl = boardEl.parentNode;
  var overlayEl = document.createElement("div");
  overlayEl.className = "overlay";
  overlayEl.setAttribute("data-testid", "game-over");
  overlayEl.textContent = "Game over";
  var scoreEl = document.getElementById("score");
  var levelEl = document.getElementById("level");
  var linesEl = document.getElementById("lines");
    if (status === "gameover") {
      if (!overlayEl.parentNode) boardWrapEl.appendChild(overlayEl);
    } else if (overlayEl.parentNode) {
      overlayEl.parentNode.removeChild(overlayEl);
    }
    renderNext();
    renderHold();
  }

  // ---- Game control ----
  function validTypes(queue) {
    if (!Array.isArray(queue)) return [];
    return queue.filter(function (t) { return SHAPES.hasOwnProperty(t); });
  }

  function newGame(queue) {
    board = emptyBoard();
    score = 0;
    level = 1;
    lines = 0;
    status = "running";
    current = null;
    held = null;
    holdUsed = false;
    bag = [];
    if (Array.isArray(queue)) {
      next = validTypes(queue);
      scripted = true;
    } else {
      next = [];
      scripted = false;
    }
    spawn();
    startTimer();
    render();
  }

  function setQueue(queue) {
    next = validTypes(queue);
    scripted = true;
    render();
  }

  function setBoard(rows) {
    var b = emptyBoard();
    for (var r = 0; r < ROWS; r++) {
      var line = (rows && rows[r]) || "";
      for (var c = 0; c < COLS; c++) {
        var ch = line.charAt(c);
        b[r][c] = SHAPES.hasOwnProperty(ch) ? ch : "";
      }
    }
    board = b;
    render();
  }

  function getBoard() {
    return board.map(function (row) {
      return row.map(function (v) { return v || "."; }).join("");
    });
  }

  function getState() {
    var cur = null;
    if (current) {
      var cells = shapeCells(current.matrix, current.row, current.col);
      cells.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
      cur = { type: current.type, cells: cells };
    }
    return {
      current: cur,
      next: next.slice(),
      score: score,
      level: level,
      lines: lines,
      dropInterval: dropInterval(),
      hold: held,
      status: status
    };
  }

  function setLevel(n) {
    var value = Math.floor(Number(n));
    if (!(value >= 1)) return;
    setLevelValue(value);
    render();
  }

  function tick(n) {
    var steps = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
    for (var i = 0; i < steps; i++) gravityStep();
    render();
  }

  window.__tetris = {
    newGame: newGame,
    setQueue: setQueue,
    setBoard: setBoard,
    tick: tick,
    setLevel: setLevel,
    input: function (action) { applyInput(action); render(); },
    getBoard: getBoard,
    getState: getState
  };

  // ---- Keyboard ----
  var KEYS = {
    ArrowLeft: "left",
    ArrowRight: "right",
    ArrowDown: "softDrop",
    " ": "hardDrop",
    ArrowUp: "rotateCW",
    c: "hold",
    C: "hold",
    Shift: "hold"
  };

  document.addEventListener("keydown", function (e) {
    var action = KEYS[e.key];
    if (!action || e.metaKey || e.ctrlKey || e.altKey) return;
    e.preventDefault();
    window.__tetris.input(action);
  });

  document.getElementById("new-game").addEventListener("click", function (e) {
    e.currentTarget.blur();
    newGame();
  });

  newGame();
})();
</script>
</body>
</html>

